/**
 * HEALTH SCORE ENGINE — Fórmula y Pesos
 * =======================================
 * El health score (0-100) mide el estado de salud de una línea y determina
 * si opera al máximo rendimiento (score alto) o de forma conservadora (score bajo).
 *
 * COMPONENTES — máximo posible entre corchetes:
 *
 *  1. success_rate_score  [0–40 pts]  ← mayor peso
 *     Tasa de envíos exitosos en los últimos 7 días.
 *     Si total_7d < 10 (historial insuficiente) se asume 80% → 32 pts.
 *
 *  2. ban_penalty  [0–30 pts]
 *     Ausencia de bans en los últimos 7 días.
 *     → 0 bans = 30 pts  |  1 ban = 15 pts  |  ≥2 bans = 0 pts
 *
 *  3. recency_score  [0–20 pts]
 *     Tiempo desde el último error. Premia la recuperación.
 *
 *  4. volume_score  [0–10 pts]
 *     Escala logarítmica de mensajes exitosos en 7 días.
 *
 *  5. burst_penalty  [−15 a 0 pts]  ← RESTA al total
 *     Detecta ráfagas de errores en las últimas 6 horas.
 *
 * NOTA v2.3+: los overrides adaptativos son re-calibrados por risk_tolerance
 * del perfil anti-ban en n04. Este nodo solo calcula el score puro.
 *
 * CASO ESPECIAL — línea nueva (total_7d === 0): score fijo = 70.
 */
const healthResult = $input.first().json;
const job          = $('Trigger – Recibe Job de Orchestrador').first().json;

const hasError = !healthResult || healthResult.error || healthResult.message;
const stats    = hasError ? {} : healthResult;

const sent7d   = Math.max(0, stats.sent_7d   || 0);
const failed7d = Math.max(0, stats.failed_7d  || 0);
const banned7d = Math.max(0, stats.banned_7d  || 0);
const errors6h = Math.max(0, stats.errors_6h  || 0);
const total7d  = Math.max(0, stats.total_7d   || 0);

const baseDailyLimit = job.phase_daily_limit || job.daily_limit || 20;
const baseMinDelay   = job.phase_min_delay   || 10;
const baseMaxDelay   = job.phase_max_delay   || 30;

if (total7d === 0) {
  return [{ json: {
    ...job,
    health_score:         70,
    health_components:    { success_rate_score: 28, ban_penalty: 30, recency_score: 12, volume_score: 0, burst_penalty: 0 },
    adaptive_daily_limit: baseDailyLimit,
    adaptive_min_delay:   baseMinDelay,
    adaptive_max_delay:   baseMaxDelay
  } }];
}

const successRatio     = total7d > 10 ? sent7d / total7d : 0.8;
const successRateScore = Math.round(Math.min(40, Math.max(0, successRatio * 40)));
const banPenalty       = Math.max(0, 30 - (banned7d * 15));

let recencyScore = 20;
if (stats.last_error_at) {
  const hoursSince = (Date.now() - new Date(stats.last_error_at).getTime()) / 3600000;
  if      (hoursSince < 1)  recencyScore = 0;
  else if (hoursSince < 6)  recencyScore = 2;
  else if (hoursSince < 12) recencyScore = 6;
  else if (hoursSince < 24) recencyScore = 12;
  else                      recencyScore = 20;
}

let volumeScore = 0;
if      (sent7d > 30) volumeScore = 10;
else if (sent7d > 15) volumeScore =  8;
else if (sent7d > 5)  volumeScore =  5;
else if (sent7d > 0)  volumeScore =  2;

const burstPenalty = errors6h >= 3 ? -15 : (errors6h >= 1 ? -5 : 0);
const healthScore  = Math.min(100, Math.max(0, successRateScore + banPenalty + recencyScore + volumeScore + burstPenalty));

const healthComponents = { success_rate_score: successRateScore, ban_penalty: banPenalty, recency_score: recencyScore, volume_score: volumeScore, burst_penalty: burstPenalty };

let adaptiveDailyLimit = baseDailyLimit;
let adaptiveMinDelay   = baseMinDelay;
let adaptiveMaxDelay   = baseMaxDelay;

if (healthScore >= 85) {
  adaptiveDailyLimit = Math.round(adaptiveDailyLimit * 1.20);
  adaptiveMinDelay   = Math.max(5, Math.round(adaptiveMinDelay * 0.80));
  adaptiveMaxDelay   = Math.max(adaptiveMinDelay, Math.round(adaptiveMaxDelay * 0.80));
} else if (healthScore <= 60) {
  adaptiveDailyLimit = Math.max(1, Math.round(adaptiveDailyLimit * 0.70));
  adaptiveMinDelay   = Math.round(adaptiveMinDelay * 1.40);
  adaptiveMaxDelay   = Math.round(adaptiveMaxDelay * 1.40);
}

return [{ json: { ...job, health_score: healthScore, health_components: healthComponents, adaptive_daily_limit: adaptiveDailyLimit, adaptive_min_delay: adaptiveMinDelay, adaptive_max_delay: adaptiveMaxDelay } }];

/**
 * APPLY ANTI-BAN PROFILE & COMPUTE DELAY — v2.4
 * ===============================================
 * Cambios v2.4 sobre v2.3:
 *   1. isProfileValid() — validación defensiva de todos los campos críticos
 *   2. console.log al activar fallback con motivo (trazabilidad en logs n8n)
 *   3. Campos applied_* en output (applied_timing_mode, applied_typing_style, etc.)
 *   4. mini_session_delay_sec y mini_session_text para el flujo de mini-sesión
 *   5. Funciones auxiliares definidas al inicio para mayor legibilidad
 *
 * FUENTES DE DATOS:
 *   n03 → health_score, adaptive_min/max_delay
 *   n22 → array Supabase o error; n04 valida y aplica fallback si es necesario
 *
 * TIMING MODES:
 *   gaussian    → distribución normal, σ=(max-min)/6
 *   uniform     → aleatorio uniforme + jitter ±10%
 *   human_noisy → uniform + 10% pausas largas (distracción humana)
 *
 * RISK TOLERANCE (calibra umbrales del Health Score override):
 *   low    → boost≥80 / penalidad≤65  (conservador — default)
 *   medium → boost≥85 / penalidad≤60
 *   high   → boost≥90 / penalidad≤55  (solo líneas maduras)
 *
 * TYPING STYLES:
 *   fixed              → 2 s fijo
 *   variable_by_length → ceil(palabras/40wpm*60), clampado 1–8 s
 *   realistic          → variable_by_length ± gaussiano 20%
 */

// ─── 1. FUNCIONES AUXILIARES ─────────────────────────────────────────────────

/** Número aleatorio ~N(0,1) via transformada Box-Muller */
function gaussianRandom() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

/** Delay en segundos según el timing_mode del perfil */
function computeDelay(mode, min, max) {
  const range = max - min;
  const mean  = min + range / 2;
  const sigma = range / 6;
  switch (mode) {
    case 'gaussian': {
      const raw = mean + gaussianRandom() * sigma;
      return Math.round(Math.min(max * 1.1, Math.max(min * 0.9, raw)));
    }
    case 'human_noisy': {
      // 10% de probabilidad de pausa larga — simula distracción humana real
      if (Math.random() < 0.10) return Math.round(max * (1.2 + Math.random() * 0.5));
      const raw = min + Math.random() * range;
      return Math.round(Math.min(max * 1.1, Math.max(min * 0.9, raw + raw * 0.08 * (Math.random() * 2 - 1))));
    }
    default: { // 'uniform'
      const base   = Math.floor(Math.random() * (range + 1)) + min;
      const jitter = Math.round(base * 0.10 * (Math.random() * 2 - 1));
      return Math.min(600, Math.max(5, base + jitter));
    }
  }
}

/** Duración de typing en segundos según typing_style y longitud del mensaje */
function computeTypingDuration(style, text) {
  const words = (text || '').trim().split(/\s+/).filter(Boolean).length;
  switch (style) {
    case 'variable_by_length':
      // ~40 palabras por minuto, clampado 1–8 s
      return Math.min(8, Math.max(1, Math.ceil(words / 40 * 60)));
    case 'realistic': {
      const base = Math.min(8, Math.max(1, Math.ceil(words / 40 * 60)));
      return Math.max(1, Math.round(base + base * 0.20 * gaussianRandom()));
    }
    default: return 2; // 'fixed'
  }
}

/**
 * Valida que el perfil cargado tenga todos los campos críticos con valores
 * admisibles. Ante cualquier campo ausente, nulo o fuera de enum → false.
 * Garantiza que nunca se ejecute con un perfil parcialmente corrupto.
 */
function isProfileValid(p) {
  if (!p || typeof p !== 'object') return false;
  const VALID_TIMING = ['gaussian', 'uniform', 'human_noisy'];
  const VALID_TYPING = ['fixed', 'variable_by_length', 'realistic'];
  const VALID_RISK   = ['low', 'medium', 'high'];
  if (typeof p.profile_name !== 'string' || !p.profile_name.trim()) return false;
  if (!VALID_TIMING.includes(p.timing_mode))                        return false;
  if (!VALID_TYPING.includes(p.typing_style))                       return false;
  if (!VALID_RISK.includes(p.risk_tolerance))                       return false;
  if (typeof p.min_delay_seconds !== 'number' || p.min_delay_seconds < 5)             return false;
  if (typeof p.max_delay_seconds !== 'number' || p.max_delay_seconds <= p.min_delay_seconds) return false;
  return true;
}

// ─── 2. FUENTES DE DATOS ────────────────────────────────────────────────────
const job         = $('Code \u2013 Compute Health Score & Adaptive Config').first().json;
const profileResp = $input.first().json;

// ─── 3. PERFIL POR DEFECTO: Meta-Stealth-2026 ───────────────────────────────
// Se activa cuando: Supabase falla | array vacío | perfil no pasa isProfileValid.
// Para agregar perfiles: INSERT INTO anti_ban_profiles en Supabase.
// Todos los campos de Supabase se fusionan sobre este objeto con spread,
// garantizando que ningún campo quede undefined.
const DEFAULT_PROFILE = {
  profile_name:                'Meta-Stealth-2026',
  timing_mode:                 'gaussian',
  min_delay_seconds:           12,
  max_delay_seconds:           40,
  enable_mini_sessions:        false,
  mini_session_followup_count: 0,
  mini_session_text:           '👍',
  mini_session_delay_min:      8,
  mini_session_delay_max:      25,
  typing_style:                'variable_by_length',
  risk_tolerance:              'low',
  enable_human_noise:          true,
  recommended_for:             'L\u00edneas nuevas y campa\u00f1as cr\u00edticas \u2013 m\u00e1xima protecci\u00f3n Meta 2026'
};

// ─── 4. EXTRAER Y VALIDAR PERFIL ─────────────────────────────────────────────
let profile        = DEFAULT_PROFILE;
let fallbackUsed   = true;
let fallbackReason = 'no_profile_loaded';

if (Array.isArray(profileResp) && profileResp.length > 0) {
  const candidate = { ...DEFAULT_PROFILE, ...profileResp[0] };
  if (isProfileValid(candidate)) {
    profile        = candidate;
    fallbackUsed   = false;
    fallbackReason = null;
  } else {
    fallbackReason = 'invalid_fields_in_db_profile';
    console.log(`[WF-010a v2.4] Fallback a Meta-Stealth-2026 — perfil DB inv\u00e1lido. Motivo: ${fallbackReason}. Perfil recibido: ${JSON.stringify(profileResp[0])}`);
  }
} else if (profileResp && !profileResp.error && profileResp.profile_name) {
  // Respuesta como objeto único (no array)
  const candidate = { ...DEFAULT_PROFILE, ...profileResp };
  if (isProfileValid(candidate)) {
    profile        = candidate;
    fallbackUsed   = false;
    fallbackReason = null;
  } else {
    fallbackReason = 'invalid_fields_in_single_profile';
    console.log(`[WF-010a v2.4] Fallback a Meta-Stealth-2026 — campos fuera de rango. Motivo: ${fallbackReason}.`);
  }
} else {
  fallbackReason = (Array.isArray(profileResp) && profileResp.length === 0)
    ? 'no_matching_profile_in_db'
    : 'supabase_error_or_null_response';
  console.log(`[WF-010a v2.4] Fallback a Meta-Stealth-2026 — razón: ${fallbackReason}.`);
}

// ─── 5. VALIDACIÓN DE CAMPOS REQUERIDOS DEL JOB ──────────────────────────────
const required = ['warmup_number_id', 'instance_name', 'recipient_phone', 'message_text', 'contact_id'];
const missing  = required.filter(f => !job[f]);
if (missing.length) throw new Error(`Job inv\u00e1lido \u2014 faltan campos: ${missing.join(', ')}`);

// ─── 6. BASE DELAYS: perfil tiene prioridad sobre adaptive del Health Score ──
let minDelay = Math.max(5, profile.min_delay_seconds);
let maxDelay = Math.max(minDelay + 5, profile.max_delay_seconds);

// ─── 7. RE-OVERRIDE POR RISK TOLERANCE ───────────────────────────────────────
// Ajusta los umbrales del Health Score override según la tolerancia al riesgo.
const score = job.health_score || 70;
const RISK_THRESHOLDS = {
  low:    { boost: 80, penalty: 65 },
  medium: { boost: 85, penalty: 60 },
  high:   { boost: 90, penalty: 55 }
};
const { boost: boostThr, penalty: penaltyThr } =
  RISK_THRESHOLDS[profile.risk_tolerance] || RISK_THRESHOLDS.medium;

if (score >= boostThr) {
  minDelay = Math.max(5, Math.round(minDelay * 0.80));
  maxDelay = Math.max(minDelay, Math.round(maxDelay * 0.80));
} else if (score <= penaltyThr) {
  minDelay = Math.round(minDelay * 1.40);
  maxDelay = Math.round(maxDelay * 1.40);
}

// ─── 8. CALCULAR DELAY PRINCIPAL ─────────────────────────────────────────────
let delaySec = computeDelay(profile.timing_mode, minDelay, maxDelay);
delaySec = Math.min(600, Math.max(5, delaySec));

// Micro-ruido ±5% adicional cuando enable_human_noise está activo
if (profile.enable_human_noise) {
  const micro = Math.round(delaySec * 0.05 * (Math.random() * 2 - 1));
  delaySec = Math.max(5, delaySec + micro);
}

// ─── 9. CALCULAR DURACIÓN DE TYPING ──────────────────────────────────────────
const typingDurationSec = computeTypingDuration(
  profile.typing_style,
  job.message_text || ''
);

// ─── 10. CALCULAR DELAY DE MINI-SESIÓN ───────────────────────────────────────
// Gaussiano entre los límites del perfil (default 8–25 s).
// Solo se usa si enable_mini_sessions=true; calcularlo siempre es inocuo.
const miniMin          = Math.max(5,  profile.mini_session_delay_min || 8);
const miniMax          = Math.max(10, profile.mini_session_delay_max || 25);
const miniSessionDelaySec = computeDelay('gaussian', miniMin, miniMax);

// ─── 11. OUTPUT ──────────────────────────────────────────────────────────────
return [{ json: {
  ...job,
  // Timing principal
  delay_sec:                   delaySec,
  typing_duration_sec:         typingDurationSec,
  final_min_delay:             minDelay,
  final_max_delay:             maxDelay,
  // Perfil aplicado (expuesto en applied_* en Set – Final Output)
  anti_ban_profile_name:       profile.profile_name,
  anti_ban_risk_tolerance:     profile.risk_tolerance,
  applied_timing_mode:         profile.timing_mode,
  applied_typing_style:        profile.typing_style,
  fallback_profile_used:       fallbackUsed,
  fallback_reason:             fallbackReason,
  // Mini-sesión
  enable_mini_sessions:        profile.enable_mini_sessions  || false,
  mini_session_followup_count: profile.mini_session_followup_count || 0,
  mini_session_text:           profile.mini_session_text || '👍',
  mini_session_delay_sec:      miniSessionDelaySec
} }];

/*
 * Clasifica el resultado de Evolution API (intento 1/3).
 *
 * Tipos de error:
 *   permanent_ban   → 403/401 o keywords de ban  — NO reintentar
 *   rate_limited    → 429 o "rate limit" en body  — SÍ reintentar (backoff 2s)
 *   temporary_block → 5xx o "unavailable"         — NO reintentar (fallo de infra)
 *   network_error   → timeout, status 0           — SÍ reintentar (backoff 2s)
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: !success && (errorType === 'network_error' || errorType === 'rate_limited'), status_code: status, attempt: 1 } }];

/*
 * Clasifica el resultado de Evolution API (intento 2/3).
 * Si falla con error transitorio → reintenta con backoff 4s (intento final).
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: !success && (errorType === 'network_error' || errorType === 'rate_limited'), status_code: status, attempt: 2 } }];

/*
 * Clasifica el resultado del último intento (3/3).
 * needs_retry = false SIEMPRE — el flujo avanza al registro.
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
}

return [{ json: { ...payload, send_success: success, is_banned: errorType === 'permanent_ban', error_type: errorType, needs_retry: false, status_code: status, attempt: 3 } }];

/*
 * CLASSIFY MINI-SESSION RESULT
 * =============================
 * Clasifica el resultado HTTP de la mini-sesión (intento único, sin reintentos).
 * Lógica IDÉNTICA a los intentos principales (n11/n15/n19): misma clasificación,
 * mismas keywords de ban, mismo árbol de decisión.
 *
 * La mini-sesión es best-effort: fallo aquí NO afecta al mensaje principal,
 * que ya fue enviado y registrado antes de llegar a este punto.
 *
 * OUTPUT:
 *   mini_session_executed   → true  (siempre: este nodo solo corre si hubo intento)
 *   mini_session_success    → true si HTTP 2xx, false si error
 *   mini_session_error_type → 'permanent_ban' | 'rate_limited' |
 *                             'temporary_block' | 'network_error' | null
 *
 * Fuente de datos del mensaje principal: $('Set – Main Payload').mainPayload
 * (los campos send_success, attempt, etc. del mensaje principal se preservan).
 */
const resp    = $input.first().json;
const payload = $('Set – Main Payload').first().json.mainPayload;

const status  = resp.statusCode || resp.status || 0;
const bodyStr = JSON.stringify(resp.body ?? resp).toLowerCase();
const success = status >= 200 && status <= 299;

let errorType = null;
if (!success) {
  const isBanKw = ['banned','blocked','unauthorized','not connected','forbidden','instance not found'].some(k => bodyStr.includes(k));
  if      (status === 403 || status === 401 || isBanKw)                                        errorType = 'permanent_ban';
  else if (status === 429 || bodyStr.includes('rate limit') || bodyStr.includes('too many'))   errorType = 'rate_limited';
  else if (status >= 500  || bodyStr.includes('unavailable') || bodyStr.includes('service error')) errorType = 'temporary_block';
  else                                                                                           errorType = 'network_error';
  console.log(`[WF-010a v2.6] Mini-sesión falló. error_type: ${errorType}. HTTP status: ${status}.`);
}

return [{ json: {
  ...payload,
  mini_session_executed:   true,
  mini_session_success:    success,
  mini_session_error_type: errorType
} }];
